{
  "items": [
    {
      "name": "Submodule.mem_of_span_top_of_smul_mem",
      "module_name": "Mathlib.RingTheory.Ideal.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} {M : Type v} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M] (M' : Submodule R M)\n  (s : Set R), Ideal.span s = ⊤ → ∀ (x : M), (∀ (r : ↑s), ↑r • x ∈ M') → x ∈ M'"
    },
    {
      "name": "Submodule.mem_of_span_eq_top_of_smul_pow_mem",
      "module_name": "Mathlib.RingTheory.Ideal.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} {M : Type v} [inst : CommSemiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  (M' : Submodule R M) (s : Set R), Ideal.span s = ⊤ → ∀ (x : M), (∀ (r : ↑s), ∃ n, ↑r ^ n • x ∈ M') → x ∈ M'"
    },
    {
      "name": "Ideal.mem_of_one_mem",
      "module_name": "Mathlib.RingTheory.Ideal.GoingUp",
      "kind": "theorem",
      "type": "∀ {S : Type u_2} [inst : CommRing S] {I : Ideal S}, 1 ∈ I → ∀ (x : S), x ∈ I"
    },
    {
      "name": "Ideal.mem_span_singleton_self",
      "module_name": "Mathlib.RingTheory.Ideal.Span",
      "kind": "theorem",
      "type": "∀ {α : Type u} [inst : Semiring α] (x : α), x ∈ Ideal.span {x}"
    },
    {
      "name": "Ideal.span_singleton_eq_top",
      "module_name": "Mathlib.RingTheory.Ideal.Span",
      "kind": "theorem",
      "type": "∀ {α : Type u} [inst : CommSemiring α] {x : α}, Ideal.span {x} = ⊤ ↔ IsUnit x"
    },
    {
      "name": "Ideal.span_singleton_le_iff_mem",
      "module_name": "Mathlib.RingTheory.Ideal.Span",
      "kind": "theorem",
      "type": "∀ {α : Type u} [inst : Semiring α] (I : Ideal α) {x : α}, Ideal.span {x} ≤ I ↔ x ∈ I"
    },
    {
      "name": "Submodule.IsPrincipal.mem_iff_generator_dvd",
      "module_name": "Mathlib.RingTheory.PrincipalIdealDomain",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] (S : Ideal R) [inst_1 : Submodule.IsPrincipal S] {x : R},\n  x ∈ S ↔ Submodule.IsPrincipal.generator S ∣ x"
    },
    {
      "name": "Submodule.IsPrincipal.generator_mem",
      "module_name": "Mathlib.RingTheory.PrincipalIdealDomain",
      "kind": "theorem",
      "type": "∀ {R : Type u} {M : Type v} [inst : AddCommMonoid M] [inst_1 : Semiring R] [inst_2 : Module R M] (S : Submodule R M)\n  [inst_3 : S.IsPrincipal], Submodule.IsPrincipal.generator S ∈ S"
    }
  ]
}
